    need(bytes.length===before.size&&before.size===after.size&&before.mtimeMs===after.mtimeMs&&before.ctimeMs===after.ctimeMs,
      'ADJUSTMENT_FILE_CHANGED','The adjustment input changed while it was being read.',409);
    let value;try{value=JSON.parse(bytes.toString('utf8'));}catch{}
    need(object(value),'INVALID_ADJUSTMENT_JSON','The adjustment input must contain one JSON object.');return value;
  }finally{await handle.close();}
}
async function retainFile(filename,bytes){
  const path=resolve(filename),handle=await open(path,constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL|constants.O_NOFOLLOW,0o600);
  try{await handle.writeFile(bytes);await handle.sync();}finally{await handle.close();}
  return {path,bytes:bytes.length,sha256:digest(bytes)};
}
function compact(result){
  return {adjustment:result.adjustment,duplicate:Boolean(result.duplicate),revision:result.state.revision};
}

export async function adjustmentsMain(argv,{signal}={}){
  if(!argv.length||argv.length===1&&['--help','help'].includes(argv[0])||argv.length===2&&argv[1]==='--help'){
    process.stdout.write(ADJUSTMENTS_HELP);return;
  }
  const {command,options}=argumentsFor(argv),controller=signal?null:new AbortController();
  signal??=controller.signal;
  const stop=()=>controller?.abort();
  if(controller){process.once('SIGINT',stop);process.once('SIGTERM',stop);}
  let workspace,onAbort;
  try{
    signal.throwIfAborted();
    const url=options['--url']?endpoint(options['--url']):null;
    if(url)need(!options['--rpc-proxy-env'],'SERVER_PROXY_CONFIGURATION',
      'Configure --rpc-proxy-env when starting the original workspace server.');
    else{
      const directory=resolve(options['--workspace']),info=await lstat(directory);
      need(info.isDirectory()&&!info.isSymbolicLink(),'EXISTING_WORKSPACE_REQUIRED','Reopen the existing original workspace directory.');
      const retainedState=await lstat(resolve(directory,'workspace.json'));
      need(retainedState.isFile()&&!retainedState.isSymbolicLink(),'EXISTING_WORKSPACE_REQUIRED','Select the retained original accounting workspace.');
      workspace=await openAccountingWorkspace({directory});
      workspace.adjustments.configureTransport({httpsProxyEnv:options['--rpc-proxy-env']});
      onAbort=()=>workspace.adjustments.close();
      signal.addEventListener('abort',onAbort,{once:true});
      signal.throwIfAborted();
    }
    const request=async(path,value,{file=false}={})=>{
      signal.throwIfAborted();
      if(workspace){
        const parsed=new URL(path,'http://workspace');
        const result=await handleAdjustmentRequest(workspace.adjustments,{
          method:value===undefined?'GET':'POST',path:parsed.pathname,
          query:Object.fromEntries(parsed.searchParams),value
        });
        need(result,'NOT_FOUND','This adjustment operation was not found.',404);
        return file?result.file:result.value;
      }
      let response;
      try{response=await fetch(new URL(path,url),{
        method:value===undefined?'GET':'POST',signal,redirect:'error',cache:'no-store',
        ...(value===undefined?{}:{headers:{'Content-Type':'application/json','X-Workspace-Request':'1'},body:JSON.stringify(value)})
      });}catch(error){
        if(signal.aborted)throw error;
        throw new WorkspaceError('WORKSPACE_UNREACHABLE','The original workspace at '+url.origin+
          ' could not be reached ('+(error.cause?.code??error.code??error.name)+'). Use its current printed local address.');
      }
      if(!response.ok){
        let error;try{error=await response.json();}catch{}
        throw new WorkspaceError(error?.error??'WORKSPACE_OPERATION_FAILED',
          error?.message??'The local workspace returned HTTP '+response.status+'.',response.status);
      }
      return file?{bytes:Buffer.from(await response.arrayBuffer()),type:response.headers.get('content-type')}:response.json();
    };
    const eventPath=(name,values)=>'/api/adjustments/'+name+'?'+new URLSearchParams(values);
    const id=()=>encodeURIComponent(required(options,'--id'));
    const mutation=()=>({revision:revision(options),actor:required(options,'--actor')});
    let result;
    if(command==='status')result=await request('/api/adjustments');
    else if(command==='events'){
      const query={runId:required(options,'--run')};
      for(const [flag,name] of [['--search','search'],['--offset','offset'],['--limit','limit']])
        if(options[flag]!==undefined)query[name]=options[flag];
      result=await request(eventPath('events',query));
    }else if(command==='event')result=await request(eventPath('event',{
      runId:required(options,'--run'),eventId:required(options,'--event')
    }));
    else if(command==='detail')result=await request('/api/adjustments/'+id());
    else if(command==='job')result=await request('/api/adjustments/jobs/'+id());
    else if(command==='preview'){
      const output=required(options,'--out'),input=await readJsonFile(required(options,'--input'));
      const preview=await request('/api/adjustments/preview',input);
      result={file:await retainFile(output,json(preview)),request:preview.request,
        previewSha256:preview.previewSha256,workspaceRevision:preview.workspaceRevision};
    }else if(command==='record'){
      const preview=await readJsonFile(required(options,'--preview'));
      need(object(preview.request)&&/^[a-f0-9]{64}$/.test(preview.previewSha256??'')&&
        Number.isSafeInteger(preview.workspaceRevision)&&preview.workspaceRevision>=0,
        'INVALID_PREVIEW_FILE','Use the complete retained output from adjustments preview.');
      result=compact(await request('/api/adjustments/record',{
        ...preview.request,revision:preview.workspaceRevision,previewSha256:preview.previewSha256
      }));
    }else if(command==='verify'){
      const adjustmentId=id(),body={...mutation(),transaction:required(options,'--transaction').trim().toLowerCase()};
      if(options['--rpc-endpoint'])body.rpcEndpoint=options['--rpc-endpoint'];
      const queued=await request('/api/adjustments/'+adjustmentId+'/verify',body);
      const jobId=queued.job.id;
      process.stderr.write('Saved return verification job '+jobId+'. Waiting for its result.\n');
      let job;
      if(workspace)job=await workspace.adjustments.waitForJob(jobId);
      else{
        do{
          job=await request('/api/adjustments/jobs/'+encodeURIComponent(jobId));
          if(['QUEUED','RUNNING'].includes(job.status))await delay(750,undefined,{signal});
        }while(['QUEUED','RUNNING'].includes(job.status));
      }
      const retained=await request('/api/adjustments/'+adjustmentId);
      result={adjustment:retained.adjustment,job,revision:(await request('/api/adjustments')).revision};
      if(job.status!=='COMPLETED'){
        emit(result);
        throw new WorkspaceError(job.error?.code??'REFUND_VERIFICATION_FAILED',
          job.error?.message??'The retained return verification ended with status '+job.status+'.');
      }
    }else if(command==='withdraw'){
      result=compact(await request('/api/adjustments/'+id()+'/withdraw',{
        ...mutation(),reason:required(options,'--reason')
      }));
    }else if(command==='export'){
      const output=required(options,'--out'),format=options['--format']??'json';
      need(['json','csv','html'].includes(format),'INVALID_EXPORT_FORMAT','Choose json, csv or html.');
      const file=await request(eventPath('export',{runId:required(options,'--run'),format}),undefined,{file:true});
      result={file:await retainFile(output,file.bytes),type:file.type};
    }
    emit(result);return result;
  }finally{
    if(onAbort)signal.removeEventListener('abort',onAbort);
    try{await workspace?.close();}
    finally{if(controller){process.removeListener('SIGINT',stop);process.removeListener('SIGTERM',stop);}}
  }
}

// MIT. Load an operator-selected JSON dataset once, before serving or export.
import { open, stat } from 'node:fs/promises';

const MAX_BYTES = 1024 * 1024;

export function validateResponseFile(value) {
  if (typeof value !== 'string' || !value.trim() || value.includes('\0'))
    throw new TypeError('responseFile must name a local JSON file');
  return value;
}

/** Preserve source bytes for export; provide valid JSON bytes for every value type. */
export async function readJsonResponseFile(path) {
  validateResponseFile(path);
  const selected = await stat(path);
  if (!selected.isFile() || selected.size > MAX_BYTES)
    throw new RangeError('responseFile must be a regular JSON file up to 1 MiB');
  const file = await open(path, 'r');
  try {
    const info = await file.stat();
    if (!info.isFile() || info.size > MAX_BYTES)
      throw new RangeError('responseFile must be a regular JSON file up to 1 MiB');
    const buffer = Buffer.alloc(MAX_BYTES + 1);
    let length = 0;
    while (length < buffer.length) {
      const { bytesRead } = await file.read(buffer, length, buffer.length - length, length);
      if (!bytesRead) break;
      length += bytesRead;
    }
    if (length > MAX_BYTES) throw new RangeError('responseFile exceeds 1 MiB');
    const source = buffer.subarray(0, length);
    const text = new TextDecoder('utf-8', { fatal: true }).decode(source);
    JSON.parse(text);
    const body = Buffer.from(text);
    if (body.length > MAX_BYTES) throw new RangeError('Encoded responseFile exceeds 1 MiB');
    return { source, body };
  } finally {
    await file.close();
  }
}

// MIT. Authenticated local operator surface for the retained Grants.gov workspace.
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomBytes, randomUUID, timingSafeEqual } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { openGrantsWorkspace } from './workspace.mjs';

const ASSETS = JSON.parse(readFileSync(new URL('./browser-assets.json',import.meta.url),'utf8'));
const STATIC = Object.freeze(Object.fromEntries(ASSETS.routes));
const own = Object.prototype.hasOwnProperty;
const error = (code,message,status=400) => Object.assign(new Error(message),{code,status});
const object = value => value!==null && typeof value==='object' && !Array.isArray(value);
const iso = () => new Date().toISOString();
const jsonBytes = value => Buffer.from(JSON.stringify(value)+'\n');

export async function grantsAction(workspace,action,input={}) {
  if(!object(input))throw error('ACTION_INPUT_REQUIRED','Send an action input object.');
  switch(action) {
    case 'workspace.status':return workspace.snapshot();
    case 'query.save':return workspace.querySave(input);
    case 'capture.start':return workspace.startCapture(input);
    case 'capture.status':return workspace.captureStatus(input.captureId);
    case 'capture.pause':return workspace.pauseCapture(input.captureId);
    case 'capture.wait':return workspace.waitCapture(input.captureId);
    case 'capture.import':return workspace.importOriginal(input);
    case 'edition.create':return workspace.createEdition(input);
    case 'edition.receive':return workspace.receiveEdition(input);
    case 'edition.read':return workspace.edition(input.editionId);
    case 'opportunity.list':return workspace.rows(input.editionId,input);
    case 'opportunity.read':return workspace.opportunity(input.editionId,input.opportunityId);
    case 'review.save':return workspace.reviewSave(input);
    case 'edition.compare':return workspace.compare(input.before,input.after,input);
    case 'workshare.read':return workspace.workshare(input.editionId,input.opportunityId,input);
    case 'merchant.create':return workspace.merchant(input);
    case 'merchant.preview':return workspace.merchantPreview(input.merchantId,input.query??{});
    case 'merchant.read':return workspace.merchantFiles(input.merchantId);
    case 'export.create':return workspace.exportFile(input);
    case 'export.read':return workspace.readExport(input.id,input);
    case 'workspace.restore':return workspace.restore(input);
    case 'publisher.status':return workspace.publisherState();
    case 'publisher.export':return workspace.publisherExport(input.kind,input.id);
    default:
      if(typeof action==='string'&&action.startsWith('publisher.'))return workspace.publisherAction(action,input);
      throw error('ACTION_UNKNOWN','Choose an available Grants.gov workspace action.',404);
  }
}

async function readJSON(request,maximum) {
  if(!/^application\/json(?:;|$)/i.test(request.headers['content-type']??''))
    throw error('JSON_REQUIRED','Use an application/json request.',415);
  const claimed=request.headers['content-length'];
  if(claimed!==undefined&&(!/^\d+$/.test(claimed)||Number(claimed)>maximum))
    throw error('REQUEST_TOO_LARGE','The request exceeds this host’s configured size.',413);
  const parts=[];let length=0;
  for await(const part of request) {
    length+=part.length;
    if(length>maximum)throw error('REQUEST_TOO_LARGE','The request exceeds this host’s configured size.',413);
    parts.push(part);
  }
  try {
    const input=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Buffer.concat(parts)));
    if(!object(input))throw Error('object');
    return input;
  } catch {throw error('JSON_INVALID','Send one complete JSON object.');}
}

/** Binds only 127.0.0.1. A random token is delivered once in the URL fragment,
 * removed from the address bar by the page, and sent in Authorization headers.
 * All source and receiving files enter as complete packets or host CLI paths. */
export async function startGrantsServer({directory,workspace,port=0,token,
  buyerWorkspaces=[],transport,maxRequestBytes=256*1024*1024}={}) {
  if(!Number.isInteger(port)||port<0||port>65535)throw error('PORT_INVALID','Use a port from 0 to 65535.');
  if(!Number.isSafeInteger(maxRequestBytes)||maxRequestBytes<1024||maxRequestBytes>1024*1024*1024)
    throw error('REQUEST_LIMIT_INVALID','Configure a request limit from 1 KiB to 1 GiB.');
  token??=randomBytes(32).toString('base64url');
  if(typeof token!=='string'||!/^[A-Za-z0-9_-]{32,256}$/.test(token))
    throw error('SESSION_TOKEN_INVALID','Configure a random local session token.');
  const expected=Buffer.from('Bearer '+token),instanceId=randomUUID();
  const ownsWorkspace=!workspace;
  workspace??=await openGrantsWorkspace({directory,transport,buyerWorkspaces});
  const assets=new Map();
  try{for(const [path,[file,type]]of Object.entries(STATIC))
    assets.set(path,{data:await readFile(new URL(file,import.meta.url)),type});}
  catch(failure){if(ownsWorkspace)await workspace.close();throw failure;}
  let origin,closePromise,closing=false;
  const respond=(response,status,value,type='application/json; charset=utf-8',headers={})=>{
    const content=Buffer.isBuffer(value)?value:jsonBytes(value);
    response.writeHead(status,{
      'Content-Type':type,'Content-Length':String(content.length),
      'Cache-Control':'no-store','X-Content-Type-Options':'nosniff',
      'Referrer-Policy':'no-referrer','Cross-Origin-Resource-Policy':'same-origin',
      'Content-Security-Policy':"default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
      ...headers
    });response.end(content);
  };
  const authorize=request=>{
    const actual=Buffer.from(request.headers.authorization??'');
    if(actual.length!==expected.length||!timingSafeEqual(actual,expected))
      throw error('SESSION_REQUIRED','Open the current local workspace link.',401);
    if(request.headers.origin!==undefined&&request.headers.origin!==origin)
      throw error('ORIGIN_MISMATCH','Use the original local workspace page.',403);
    if(request.headers['sec-fetch-site']==='cross-site')
      throw error('ORIGIN_MISMATCH','Use the original local workspace page.',403);
  };
  const server=createServer(async(request,response)=>{
    try{
      if(closing)throw error('WORKSPACE_CLOSING','The local workspace is closing.',503);
      if(request.headers.host!==new URL(origin).host)
        throw error('HOST_MISMATCH','Use the original local workspace address.',403);
      const target=new URL(request.url,origin),method=request.method;
      if(target.origin!==origin||target.username||target.password)throw error('TARGET_INVALID','Use a local workspace path.');
      if(method==='GET'&&assets.has(target.pathname)) {
        const asset=assets.get(target.pathname);return respond(response,200,asset.data,asset.type);
      }
      authorize(request);
      if(method==='GET'&&target.pathname==='/api/identity'){
        const state=await workspace.snapshot();
        return respond(response,200,{ok:true,result:{schema:'stellar-forge.grantsgov-session.v1',
          instanceId,pid:process.pid,workspaceId:state.id,createdAt:state.createdAt}});
      }
      if(method==='GET'&&target.pathname==='/api/state')
        return respond(response,200,{ok:true,result:await workspace.snapshot()});
      if(method==='POST'&&target.pathname==='/api/action') {
        const payload=await readJSON(request,maxRequestBytes);
        if(typeof payload.action!=='string'||Object.keys(payload).some(key=>!['action','input'].includes(key)))
          throw error('ACTION_REQUIRED','Send action and input.');
        const result=await grantsAction(workspace,payload.action,payload.input??{});
        return respond(response,200,{ok:true,result});
      }
      if(method==='GET'&&/^\/api\/exports\/[a-f0-9]{64}$/.test(target.pathname)) {
        const id=target.pathname.split('/').at(-1);
        const first=await workspace.readExport(id,{offset:0,limit:8*1024*1024}),parts=[Buffer.from(first.data,'base64')];
        let next=first.nextOffset;
        while(next!==null){const part=await workspace.readExport(id,{offset:next,limit:8*1024*1024});
          parts.push(Buffer.from(part.data,'base64'));next=part.nextOffset;}
        const data=Buffer.concat(parts);
        return respond(response,200,data,'application/octet-stream',{
          'Content-Disposition':'attachment; filename="'+first.file.name+'"',
          'X-Content-SHA256':first.file.sha256
        });
      }
      throw error('ROUTE_MISSING','This local workspace route is unavailable.',404);
    }catch(failure){
      const status=Number.isInteger(failure.status)&&failure.status>=400&&failure.status<=599?failure.status:500;
      if(!response.headersSent)respond(response,status,{ok:false,error:{code:failure.code??'WORKSPACE_ACTION_FAILED',
        message:failure.message??'The workspace action failed.',at:iso()}});
      else response.destroy();
    }
  });
  server.requestTimeout=10*60*1000;server.headersTimeout=30*1000;
  server.keepAliveTimeout=5000;server.maxHeadersCount=80;
  await new Promise((accept,reject)=>{
    server.once('error',reject);
    server.listen(port,'127.0.0.1',()=>{server.off('error',reject);accept();});
  }).catch(async failure=>{if(ownsWorkspace)await workspace.close();throw failure;});
  origin='http://127.0.0.1:'+server.address().port;
  const close=()=>closePromise??=(async()=>{
    closing=true;
    if(ownsWorkspace)await workspace.close();
    await new Promise((accept,reject)=>{server.close(failure=>failure?reject(failure):accept());server.closeIdleConnections?.();});
  })();
  return {server,workspace,origin,url:origin+'/#session='+token,token,instanceId,close};
}

// MIT. Exact monthly tariff planning over the original SF97 merchant review.
import { createHash } from 'node:crypto';
import { analyze } from '../analyze.mjs';

export const TARIFF_REVIEW_SCHEMA = 'stellar-forge.merchant-tariff-review.v1';
export const TARIFF_QUOTE_SCHEMA = 'stellar-forge.merchant-tariff-quote.v1';
export const TARIFF_LIMITS = Object.freeze({ tariffs:12, volumes:24, tiers:64 });

const MICRO = 1_000_000n;
const MAX_QUANTITY = BigInt(Number.MAX_SAFE_INTEGER);
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value)
  && [Object.prototype, null].includes(Object.getPrototypeOf(value));
const canonical = value => JSON.stringify(value, (_, item) => plain(item)
  ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
const fingerprint = value => createHash('sha256').update(canonical(value)).digest('hex');
const fail = (code, message, status = 422) => Object.assign(new TypeError(message), { code, status });
const clone = value => structuredClone(value);

function record(value, label, fields = null) {
  if (!plain(value)) throw fail('TARIFF_INPUT_INVALID', label + ' must be an object.');
  if (fields) {
    const unsupported = Object.keys(value).find(key => !fields.includes(key));
    if (unsupported) throw fail('TARIFF_INPUT_INVALID', label + ' has an unsupported field: ' + unsupported + '.');
  }
  return value;
}

function quantity(value, label = 'Quantity') {
  let number;
  if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) number = BigInt(value);
  else if (typeof value === 'string' && /^(0|[1-9]\d{0,15})$/.test(value)) number = BigInt(value);
  else throw fail('TARIFF_QUANTITY_INVALID', label + ' must be a nonnegative safe integer or its canonical integer string.');
  if (number > MAX_QUANTITY)
    throw fail('TARIFF_QUANTITY_INVALID', label + ' exceeds the original merchant monthly target range.');
  return number;
}

function microUsd(value, label = 'USD amount') {
  if (typeof value !== 'string' || !/^(0|[1-9]\d*)(\.\d{1,6})?$/.test(value))
    throw fail('TARIFF_AMOUNT_INVALID', label + ' must be a nonnegative USD decimal string with at most six places.');
  const [whole, fraction = ''] = value.split('.');
  return BigInt(whole) * MICRO + BigInt(fraction.padEnd(6, '0'));
}

function decimal(value, places = 6) {
  if (value === null) return null;
  const scale = 10n ** BigInt(places), negative = value < 0n, absolute = negative ? -value : value;
  const tail = String(absolute % scale).padStart(places, '0').replace(/0+$/, '');
  return (negative ? '-' : '') + String(absolute / scale) + (tail ? '.' + tail : '');
}

const usd = value => decimal(value, 6);
const ceil = (numerator, denominator) => (numerator + denominator - 1n) / denominator;
const min = (left, right) => left < right ? left : right;

function gcd(left, right) {
  while (right) [left, right] = [right, left % right];
  return left;
}

// Fractions are authoritative; the display bounds retain twelve decimal places.
function unitFraction(totalMicroUsd, units) {
  if (!units) return null;
  const denominator = units * MICRO, divisor = gcd(totalMicroUsd, denominator);
  const scaled = totalMicroUsd * 1_000_000_000_000n;
  return {
    numerator:String(totalMicroUsd / divisor), denominator:String(denominator / divisor),
    floorUsd:decimal(scaled / denominator, 12), ceilingUsd:decimal(ceil(scaled, denominator), 12)
  };
}

function margin(contribution, gross) {
  return contribution === null || gross === 0n ? null : decimal(contribution * MICRO / gross, 4);
}

/**
 * Each upTo is a cumulative inclusive quantity. The final null is unbounded.
 * A graduated schedule prices each band separately. A volume schedule selects
 * one band from the entire monthly quantity and applies its rate to all units.
 */
export function normalizeTariff(input) {
  record(input, 'Tariff', ['id', 'label', 'routeId', 'mode', 'tiers']);
  if (typeof input.id !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(input.id) || input.id === 'baseline')
    throw fail('TARIFF_ID_INVALID', 'Use a tariff ID of 1-64 letters, digits, underscores or hyphens; baseline is reserved.');
  if (typeof input.label !== 'string' || !input.label.trim() || input.label.length > 120
      || /[\u0000-\u001f\u007f]/.test(input.label))
    throw fail('TARIFF_LABEL_INVALID', 'Give each tariff a label of 1-120 printable characters.');
  if (typeof input.routeId !== 'string' || !input.routeId || input.routeId.length > 2000
      || /[\u0000-\u001f\u007f]/.test(input.routeId))
    throw fail('TARIFF_ROUTE_INVALID', 'Select an original merchant route ID.');
  if (!['graduated', 'volume'].includes(input.mode))
    throw fail('TARIFF_MODE_INVALID', 'Choose graduated or volume pricing.');
  if (!Array.isArray(input.tiers) || !input.tiers.length || input.tiers.length > TARIFF_LIMITS.tiers)
    throw fail('TARIFF_TIERS_INVALID', 'A tariff needs 1-' + TARIFF_LIMITS.tiers + ' tiers.');

  let previous = 0n;
  const tiers = input.tiers.map((tier, index) => {
    record(tier, 'Tier ' + (index + 1), ['upTo', 'unitPriceUsd']);
    const last = index === input.tiers.length - 1;
    if (last ? tier.upTo !== null : tier.upTo === null)
      throw fail('TARIFF_BAND_INVALID', 'Only the final tier has an unbounded null upTo.');
    let cap = null;
    if (tier.upTo !== null) {
      cap = quantity(tier.upTo, 'Tier ' + (index + 1) + ' upper quantity');
      if (cap <= previous)
        throw fail('TARIFF_BAND_INVALID', 'Finite tier quantities must be positive and strictly increasing.');
      previous = cap;
    }
    if (typeof tier.unitPriceUsd !== 'string' || tier.unitPriceUsd.length > 64)
      throw fail('TARIFF_AMOUNT_INVALID', 'Tier unit price must be a USD string of at most 64 characters.');
    const rate = microUsd(tier.unitPriceUsd, 'Tier ' + (index + 1) + ' unit price');
    return { upTo:cap === null ? null : String(cap), unitPriceUsd:usd(rate) };
  });
  return { id:input.id, label:input.label.trim(), routeId:input.routeId, mode:input.mode, tiers };
}

function calculate(tariff, units) {
  if (!units) return { total:0n, lines:[], selectedTier:null };
  let lower = 0n, total = 0n, selectedTier = null;
  const lines = [];
  for (let index = 0; index < tariff.tiers.length; index++) {
    const tier = tariff.tiers[index], cap = tier.upTo === null ? null : BigInt(tier.upTo);
    const price = microUsd(tier.unitPriceUsd);
    if (tariff.mode === 'volume') {
      if (cap !== null && units > cap) { lower = cap; continue; }
      total = units * price;
      lines.push({ tierIndex:index, lowerExclusiveQuantity:String(lower), upTo:tier.upTo,
        quantity:String(units), unitPriceUsd:tier.unitPriceUsd, subtotalUsd:usd(total) });
      selectedTier = index;
      break;
    }
    const upper = cap === null ? units : min(units, cap), used = upper - lower;
    if (used > 0n) {
      const subtotal = used * price;
      total += subtotal;
      lines.push({ tierIndex:index, lowerExclusiveQuantity:String(lower), upTo:tier.upTo,
        quantity:String(used), unitPriceUsd:tier.unitPriceUsd, subtotalUsd:usd(subtotal) });
      selectedTier = index;
    }
    if (units <= upper) break;
    lower = cap;
  }
  return { total, lines, selectedTier };
}

/** Exact schedule result and the separately derived six-place uniform quote. */
export function quoteTariff(input, requestedQuantity) {
  const tariff = normalizeTariff(input), units = quantity(requestedQuantity);
  const calculation = calculate(tariff, units);
  const uniform = units ? ceil(calculation.total, units) : null;
  const uniformGross = uniform === null ? null : uniform * units;
  const next = units < MAX_QUANTITY ? calculate(tariff, units + 1n) : null;
  return {
    schema:TARIFF_QUOTE_SCHEMA, tariffId:tariff.id, tariffSha256:fingerprint(tariff), mode:tariff.mode,
    quantity:String(units), totalMicroUsd:String(calculation.total), totalUsd:usd(calculation.total),
    selectedTier:calculation.selectedTier, lines:calculation.lines,
    effectiveUnitUsd:unitFraction(calculation.total, units),
    chosenUniformQuoteUsd:usd(uniform), uniformGrossUsd:usd(uniformGross),
    roundingDeltaUsd:uniformGross === null ? null : usd(uniformGross - calculation.total),
    rounding:'CEILING_TO_MICRO_USD_PER_REQUEST',
    nextQuantity:next === null ? null : String(units + 1n),
    nextTotalUsd:next === null ? null : usd(next.total),
    nextGrossChangeUsd:next === null ? null : usd(next.total - calculation.total),
    nextUnitPriceUsd:next === null ? null : tariff.tiers[next.selectedTier].unitPriceUsd
  };
}

function boundaries(tariff) {
  return tariff.tiers.flatMap((tier, index) => {
    if (tier.upTo === null || BigInt(tier.upTo) === MAX_QUANTITY) return [];
    const beforeQuantity = BigInt(tier.upTo), before = calculate(tariff, beforeQuantity);
    const after = calculate(tariff, beforeQuantity + 1n), change = after.total - before.total;
    return [{
      afterTierIndex:index, beforeQuantity:String(beforeQuantity), afterQuantity:String(beforeQuantity + 1n),
      beforeTotalUsd:usd(before.total), afterTotalUsd:usd(after.total),
      grossChangeUsd:usd(change), decreasesGross:change < 0n
    }];
  });
}

function scenarioFor(tariff, quote, comparisonId) {
  if (quote.quantity === '0') return null;
  return {
    id:comparisonId,
    label:(tariff.label.slice(0, 75) + ' at ' + quote.quantity + ' requests/month').slice(0, 120),
    routes:{
      [tariff.routeId]:{
        unitPriceUsd:quote.chosenUniformQuoteUsd,
        priceBasis:'Uniform quote from ' + tariff.mode + ' tariff ' + quote.tariffSha256
          + ' at ' + quote.quantity + ' planned requests/month; CEILING(total micro-USD / quantity).',
        monthlyPaidTarget:Number(quote.quantity)
      }
    }
  };
}

function comparison(tariff, requestedQuantity, row, reviewSha256) {
  const quote = quoteTariff(tariff, requestedQuantity), units = BigInt(quote.quantity);
  const baselineGross = microUsd(row.quoteUsd) * units;
  const unitCost = row.variablePerFulfilledUsd === null ? null : microUsd(row.variablePerFulfilledUsd);
  const cost = unitCost === null ? null : unitCost * units;
  const gross = BigInt(quote.totalMicroUsd);
  const baselineContribution = cost === null ? null : baselineGross - cost;
  const contribution = cost === null ? null : gross - cost;
  const uniformGross = quote.uniformGrossUsd === null ? null : microUsd(quote.uniformGrossUsd);
  const uniformContribution = uniformGross === null || cost === null ? null : uniformGross - cost;
  const comparisonId = fingerprint({ reviewSha256, tariffId:tariff.id, quantity:quote.quantity });
  return {
    id:comparisonId, tariffId:tariff.id, routeId:tariff.routeId, quantity:quote.quantity,
    method:row.method, path:row.path, quote,
    baseline:{
      quoteUsd:row.quoteUsd, priceBasis:row.priceBasis, totalUsd:usd(baselineGross),
      contributionBeforeFixedUsd:usd(baselineContribution),
      marginBeforeFixedPct:margin(baselineContribution, baselineGross)
    },
    costs:{
      basis:'FULFILLED_REQUESTS_ONLY', perFulfilledUsd:row.variablePerFulfilledUsd,
      perChallengeUsd:row.perChallengeUsd, variableCostsUsd:usd(cost),
      unknownInputs:unitCost === null ? ['routes.' + tariff.routeId + '.perFulfilledUsd'] : []
    },
    contributionBeforeFixedUsd:usd(contribution), marginBeforeFixedPct:margin(contribution, gross),
    grossDeltaUsd:usd(gross - baselineGross),
    contributionDeltaUsd:cost === null ? null : usd(contribution - baselineContribution),
    uniformProjection:{
      grossUsd:usd(uniformGross), variableCostsUsd:quote.quantity === '0' ? null : usd(cost),
      contributionBeforeFixedUsd:usd(uniformContribution),
      marginBeforeFixedPct:uniformGross === null ? null : margin(uniformContribution, uniformGross),
      grossDeltaUsd:uniformGross === null ? null : usd(uniformGross - baselineGross)
    },
    scenario:scenarioFor(tariff, quote, comparisonId)
  };
}

/**
 * Evaluate explicit monthly targets from the saved native seller review.
 * The original analyzer validates payment bindings and selected route scope.
 * Each comparison changes one route at one volume; shared fixed cost remains
 * on the whole-seller review. Explicit selection passes the included scenario
 * to the original planner, which calculates the complete merchant forecast.
 */
export function createTariffReview({ seller, observation, terms, tariffs, volumes, provenance = {} } = {}) {
  record(provenance, 'Source provenance');
  if (!Array.isArray(tariffs) || !tariffs.length || tariffs.length > TARIFF_LIMITS.tariffs)
    throw fail('TARIFF_COUNT_INVALID', 'Compare 1-' + TARIFF_LIMITS.tariffs + ' tariff schedules.');
  if (!Array.isArray(volumes) || !volumes.length || volumes.length > TARIFF_LIMITS.volumes)
    throw fail('TARIFF_VOLUMES_INVALID', 'Enter 1-' + TARIFF_LIMITS.volumes + ' explicit monthly quantities.');
  const normalized = tariffs.map(normalizeTariff);
  if (new Set(normalized.map(tariff => tariff.id)).size !== normalized.length)
    throw fail('TARIFF_ID_DUPLICATE', 'Every tariff in a review needs its own ID.');
  const quantities = volumes.map((value, index) => String(quantity(value, 'Monthly quantity ' + (index + 1))));
  if (new Set(quantities).size !== quantities.length)
    throw fail('TARIFF_VOLUME_DUPLICATE', 'Each monthly quantity must appear once in a review.');

  // Preserve the analyzer's exact checks before using any commercial term.
  const original = analyze(seller, observation, terms, clone(provenance));
  const byRoute = new Map(original.routes.map(row => [row.routeId, row]));
  const sellerRoutes = new Set(seller.routes.map(route => route.id));
  for (const tariff of normalized) {
    if (!sellerRoutes.has(tariff.routeId))
      throw fail('TARIFF_ROUTE_UNKNOWN', 'The saved seller has no route ' + tariff.routeId + '.');
    if (!byRoute.has(tariff.routeId))
      throw fail('TARIFF_ROUTE_OUTSIDE_REVIEW', 'Route ' + tariff.routeId + ' is outside the saved review route selection.');
  }
  const source = {
    sellerCanonicalSha256:fingerprint(seller), observationCanonicalSha256:fingerprint(observation),
    termsCanonicalSha256:fingerprint(terms), provenance:clone(provenance)
  };
  const tariffReviewSha256 = fingerprint({ schema:TARIFF_REVIEW_SCHEMA, source, tariffs:normalized, volumes:quantities });
  const comparisons = normalized.flatMap(tariff => quantities.map(value =>
    comparison(tariff, value, byRoute.get(tariff.routeId), tariffReviewSha256)));
  return {
    schema:TARIFF_REVIEW_SCHEMA, tariffReviewSha256, source, generatedAt:new Date().toISOString(),
    tariffs:normalized, volumes:quantities, comparisons,
    tariffDetails:normalized.map(tariff => ({
      tariffId:tariff.id, tariffSha256:fingerprint(tariff), boundaries:boundaries(tariff)
    })),
    baseline:{
      merchantName:terms.merchantName,
      scope:original.overview.sharedFixedCostApplied === false ? 'SELECTED_CURRENT_ROUTE' : 'CURRENT_SELLER',
      sharedMonthlyFixedUsd:original.overview.sharedMonthlyFixedUsd,
      sharedFixedCostApplied:original.overview.sharedFixedCostApplied !== false,
      monthlyTargets:Object.fromEntries(original.routes.map(row => [row.routeId, row.paidTargetMonth]))
    }
  };
}

/** Return a mutable copy for the caller's explicit original-plan selection. */
export function selectionScenario(review, comparisonId) {
  record(review, 'Tariff review');
  if (review.schema !== TARIFF_REVIEW_SCHEMA || !/^[a-f0-9]{64}$/.test(review.tariffReviewSha256 ?? '')
      || !Array.isArray(review.comparisons))
    throw fail('TARIFF_REVIEW_INVALID', 'Use a complete saved tariff review.');
  if (typeof comparisonId !== 'string' || !/^[a-f0-9]{64}$/.test(comparisonId))
    throw fail('TARIFF_COMPARISON_NOT_FOUND', 'Select a comparison from this tariff review.', 404);
  const row = review.comparisons.find(item => item.id === comparisonId);
  if (!row) throw fail('TARIFF_COMPARISON_NOT_FOUND', 'The selected comparison is unavailable in this review.', 404);
  if (row.quantity === '0' || row.scenario === null)
    throw fail('TARIFF_ZERO_VOLUME', 'A uniform per-request quote requires a positive monthly quantity.');
  const expectedId = fingerprint({ reviewSha256:review.tariffReviewSha256, tariffId:row.tariffId, quantity:row.quantity });
  if (row.id !== expectedId || !plain(row.scenario) || row.scenario.id !== row.id)
    throw fail('TARIFF_REVIEW_INVALID', 'The selected comparison differs from its saved tariff identity.');
  return clone(row.scenario);
}

// MIT. Customer statements over retained native accounting and original service orders.
import {createHash} from 'node:crypto';
import {compileAccountingPeriod} from '../reconcile.mjs';
import {indexAdjustments,summarizeAdjustments,adjustmentEventKey} from '../adjustments.mjs';
