      mapping.set(row.from,row.to);if(row.to!==null)used.add(row.to);
    }
    const sourceMappings=value.originals.map(row=>({originalSourceId:row.sourceId,originalReceiptSha256:row.receiptSha256,
      localSourceId:row.localSourceId,sha256:row.sha256,bytes:row.bytes}));
    const sourceMap=new Map(value.originals.map(row=>[row.sourceId,row.localSourceId]));
    const book=structuredClone(value.input);delete book.receivedFrom;
    book.pricingVersion=input.pricingVersion;book.label=string(input.label,'Local cost review name',160);
    book.reason=string(input.reason,'Receiving and allocation reason',2000);
    book.periodAlignment={confirmed:false,reason:''};
    book.coverage=pricing.report.routes.map(row=>({routeId:row.routeId,state:'UNKNOWN',note:'',zeroCostConfirmed:false}));
    book.contextSourceIds=book.contextSourceIds.map(sourceId=>sourceMap.get(sourceId));
    book.imports=book.imports.map(row=>({...row,sourceId:sourceMap.get(row.sourceId)}));
    const lineMappings=[];
    book.lines=book.lines.map(row=>{
      const localSourceId=sourceMap.get(row.sourceId),lineId=localSourceId+':'+
        (row.sourceRow===null?'manual-'+digest(row.id).slice(0,24):row.sourceRow);
      lineMappings.push({originalLineId:row.id,localLineId:lineId,originalSourceId:row.sourceId,localSourceId});
      return {...row,id:lineId,sourceId:localSourceId,allocations:row.allocations.flatMap(allocation=>{
        const routeId=mapping.get(allocation.routeId);
        return routeId===null?[]:[{...allocation,routeId,basis:'EXPLICIT_AMOUNT',weight:null}];
      })};
    });
    const localSources=new Map(value.originals.map(row=>[row.localSourceId,{...row,sourceId:row.localSourceId}]));
    const normalized=normalizeBook(book,pricing.report,localSources);
    const origin={schema:originSchema,packageId:input.packageId,archiveSha256:selected.sha256,
      originalEdition:value.descriptor.edition,originalEditionRevision:value.descriptor.revision,
      originalPricingVersion:value.descriptor.pricingVersion,originalPricingReportSha256:value.binding.pricingReportSha256,
      pricingVersion:input.pricingVersion,pricingReportSha256:input.expectedPricingReportSha256,
      routeMappings:input.routeMappings.map(row=>({from:row.from,to:row.to})),sourceMappings,lineMappings,
      period:normalized.period,reason:normalized.reason};
    const selection={packageId:input.packageId,expectedPackageSha256:input.expectedPackageSha256,
      pricingVersion:input.pricingVersion,expectedPricingReportSha256:input.expectedPricingReportSha256,
      routeMappings:origin.routeMappings,label:normalized.label,reason:normalized.reason};
    return {selection,origin,book:normalized,report:costReport(normalized,pricing.report,localSources),
      sourceSummary:value.originals.map(row=>({sourceId:row.sourceId,localSourceId:row.localSourceId,metadata:row.metadata,sha256:row.sha256,bytes:row.bytes})),
      reviewSha256:digest(canonical({selection,origin,book:normalized})),
      sellerChanged:pricing.sellerChanged};
  }
  async function savedDraft(packageId,requestId){
    id(requestId,'Received draft request');
    const selected=await record(packageId),value=json(await readPrivate(join(folder(packageId),'drafts',requestId+'.json'),64*1024*1024));
    if(value.schema!==DRAFT||value.requestId!==requestId||value.packageId!==packageId||
        value.archiveSha256!==selected.sha256||!plain(value.book)||!plain(value.origin)||
        value.origin.schema!==originSchema||value.origin.archiveSha256!==selected.sha256||
        value.book.receivedFrom?.packageId!==packageId||value.book.receivedFrom?.draftId!==requestId)
      throw fail('DRAFT_CHANGED','The retained receiving draft has a different original source.');
    return value;
  }
  async function importDraft(input){
    id(input.requestId,'Received draft request');id(input.packageId,'Received package');requireHash(input.reviewSha256,'received draft review');
    const requestSha256=digest(canonical(input));
    try{
      const previous=await savedDraft(input.packageId,input.requestId);
      if(previous.requestSha256!==requestSha256)throw fail('REQUEST_CHANGED','The receiving draft request identifies different reviewed inputs.',409);
      return {status:'COST_DRAFT_RECEIVED',requestId:input.requestId,packageId:input.packageId,
        book:previous.book,origin:previous.origin,replayed:true};
    }catch(error){if(error.code!=='ENOENT')throw error;}
    const reviewed=await reviewDraft(input);
    if(reviewed.reviewSha256!==input.reviewSha256)throw fail('REVIEW_CHANGED','Review the exact route/source mapping before receiving a local draft.',409);
    const value=await original(input.packageId),base=await ensureFiles(input.packageId);
    for(const source of value.originals){
      const raw=await checkedFile(base,'originals/'+source.sourceId+'/original',{bytes:source.bytes,sha256:source.sha256},MAX_SOURCE);
      const adopted=await sources.upload({requestId:source.localSourceId,metadata:source.metadata,body:[raw],origin:sourceOrigin});
      if(adopted.sha256!==source.sha256||adopted.bytes!==source.bytes)
        throw fail('SOURCE_CHANGED','The native local source adoption differs from its original.');
    }
    const book={...reviewed.book,receivedFrom:{packageId:input.packageId,draftId:input.requestId}};
    const draft={schema:DRAFT,requestId:input.requestId,requestSha256,packageId:input.packageId,
      archiveSha256:input.expectedPackageSha256,createdAt:new Date().toISOString(),selection:reviewed.selection,
      origin:reviewed.origin,book};
    if(encode(draft).length>64*1024*1024)throw fail('DRAFT_TOO_LARGE','The complete received draft exceeds the original 64 MiB member limit.');
    const drafts=join(folder(input.packageId),'drafts');await privateDir(drafts,true);
    if(!await atomicJson(join(drafts,input.requestId+'.json'),draft,pending)){
      const winner=await savedDraft(input.packageId,input.requestId);
      if(winner.requestSha256!==requestSha256)throw fail('REQUEST_CHANGED','Another received draft owns this request.',409);
      return {status:'COST_DRAFT_RECEIVED',requestId:input.requestId,packageId:input.packageId,book:winner.book,origin:winner.origin,replayed:true};
    }
    return {status:'COST_DRAFT_RECEIVED',requestId:input.requestId,packageId:input.packageId,book,origin:reviewed.origin,replayed:false};
  }
  async function origin(link,pricingVersion){
    if(!plain(link)||Object.keys(link).some(key=>!['packageId','draftId'].includes(key)))throw fail('ORIGIN_INVALID','Retain the original received draft identity.');
    const saved=await savedDraft(link.packageId,link.draftId);
    if(saved.origin.pricingVersion!==pricingVersion)throw fail('PRICING_CHANGED','Receive a new explicit mapping for a different local pricing source.');
    return {...saved.origin,draftId:link.draftId,receivingRequestSha256:saved.requestSha256};
  }
  async function drafts(packageId){
    await record(packageId);const dir=join(folder(packageId),'drafts');let names;
    try{names=await readdir(dir);}catch(error){if(error.code==='ENOENT')return [];throw error;}
    const rows=[];
    for(const name of names){
      if(!/^[a-f0-9-]{36}\.json$/.test(name)||!UUID.test(name.slice(0,-5)))throw fail('DRAFT_CHANGED','Unexpected received draft record.');
      rows.push(await savedDraft(packageId,name.slice(0,-5)));
    }
    return rows.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  }
  async function items(packageId,{draftId}={}){
    const selected=await record(packageId),base=folder(packageId);
    const result=[{name:'receipt.json',read:()=>readPrivate(join(base,'receipt.json'))},
      ...selected.parts.map(part=>({name:part.name,read:()=>checkedFile(base,part.name,part,PART_BYTES)}))];
    for(const draft of await drafts(packageId)){
      if(draftId!==undefined&&draft.requestId!==draftId)continue;
      result.push({name:'drafts/'+draft.requestId+'.json',read:()=>readPrivate(join(base,'drafts',draft.requestId+'.json'),64*1024*1024)});
    }
    if(draftId!==undefined&&!result.some(row=>row.name==='drafts/'+draftId+'.json'))
      throw fail('DRAFT_CHANGED','The selected original receiving draft is missing.');
    return result;
  }
  async function request(packageId){
    try{return {status:'COMMITTED',record:summary(await record(packageId))};}
    catch(error){if(error.code!=='ENOENT')throw error;return {status:'UNKNOWN',packageId};}
  }
  async function draftSummaries(packageId){
    return {items:(await drafts(packageId)).map(value=>({requestId:value.requestId,packageId,
      label:value.book.label,pricingVersion:value.book.pricingVersion,createdAt:value.createdAt}))};
  }
  async function reopenDraft(packageId,requestId){
    const value=await savedDraft(packageId,requestId);
    return {status:'COST_DRAFT_RECEIVED',packageId,requestId,book:value.book,origin:value.origin,replayed:true};
  }
  return {root,records,list,record,inspect,download,receive,archiveFile,reviewDraft,importDraft,origin,drafts,
    savedDraft,items,request,draftSummaries,reopenDraft};
}

// MIT. Path binding for the existing SF30 HTTP adapter; no payment implementation.
const plain = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const namesAllowed = /^[A-Za-z_][A-Za-z0-9_]*$/;
const reserved = new Set(['__proto__', 'prototype', 'constructor']);
const literal = /^[A-Za-z0-9_.~-]+$/;
const badTarget = () => Object.assign(new TypeError('INVALID_REQUEST_TARGET'), { status: 400 });
// Native route regex uses /i without /u. Fold ASCII path literals only;
// preserve the casing and contents of decoded dynamic path parameters.
const asciiFold = value => value.replace(/[A-Z]/g, c => c.toLowerCase());

function decodeSegment(segment) {
  let value;
  try { value = decodeURIComponent(segment); } catch { throw badTarget(); }
  // Match native decoding exactly once. Never allow an encoded path delimiter,
  // a second decoding layer, a control character or a URL-normalized dot segment.
  if (!value || value === '.' || value === '..' || /[/\\?#%\x00-\x1f\x7f]/u.test(value)) throw badTarget();
  return value;
}

function match(binding, rawPath) {
  const values = rawPath.split('/');
  if (values.length !== binding.segments.length) return null;
  const result = Object.create(null);
  for (let i = 0; i < values.length; i++) {
    const expected = binding.segments[i];
    if (expected.startsWith(':')) result[expected.slice(1)] = decodeSegment(values[i]);
    else if (asciiFold(expected) !== asciiFold(values[i])) return null;
  }
  return result;
}

/** Bind an imported Bazaar template to its concrete, schema-checked sample URL. */
export function compileServicePath(offer) {
  const samplePath = new URL(offer.resource.url).pathname;
  const bazaar = offer.extensions?.bazaar, template = bazaar?.routeTemplate;
  const path = template ?? samplePath;
  if (typeof path !== 'string' || !path.startsWith('/') || path.includes('//') ||
      path.length > 2048 || (path.length > 1 && path.endsWith('/') && template !== undefined)) {
    throw new TypeError('Canonical service path required; dynamic trailing slashes are unsupported');
  }
  const segments = path.split('/'), names = [];
  for (let i = 1; i < segments.length; i++) {
    const segment = segments[i];
    if (template !== undefined && segment.startsWith(':')) {
      const name = segment.slice(1);
      if (!namesAllowed.test(name) || reserved.has(name) || names.includes(name))
        throw new TypeError('Unique, whole-segment named path parameters required');
      names.push(name);
    } else if ((segment && !literal.test(segment)) || segment === '.' || segment === '..' ||
               (!segment && i !== segments.length - 1)) {
      throw new TypeError('Service paths require canonical literal or whole-parameter segments');
    }
  }
  // Native 2.28.0 patterns use case-insensitive, dotAll matching. Keep a
  // matching view so a case variant cannot pick another endpoint's price.
  const nativePattern = new RegExp('^' + segments.map(segment => segment.startsWith(':')
    ? '[^/]+' : segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('/') + '$', 'is');
  const binding = Object.freeze({ path, samplePath, dynamic: names.length > 0,
    names: Object.freeze(names), segments: Object.freeze(segments), nativePattern });
  if (template !== undefined && !names.length) throw new TypeError('routeTemplate must contain a named parameter');
  if (!binding.dynamic) {
    if (bazaar?.info?.input?.pathParams !== undefined) throw new TypeError('pathParams requires routeTemplate');
    return binding;
  }
  const examples = bazaar.info?.input?.pathParams;
  const schema = bazaar.schema?.properties?.input?.properties?.pathParams;
  if (!plain(examples) || !plain(schema) || schema.type !== 'object' || !plain(schema.properties) ||
      !Array.isArray(schema.required) || schema.additionalProperties !== false ||
      Object.keys(examples).length !== names.length || Object.keys(schema.properties).length !== names.length ||
      schema.required.length !== names.length || new Set(schema.required).size !== names.length ||
      names.some(name => !Object.hasOwn(examples, name) || !Object.hasOwn(schema.properties, name) ||
        !schema.required.includes(name) || typeof examples[name] !== 'string' || schema.properties[name]?.type !== 'string')) {
    // Native Bazaar 2.28.0 enriches pathParams as strings. Preserve the original
    // schema: numeric/boolean schemas need an explicit typed native integration,
    // not silent conversion or a challenge that disagrees with native checkout.
    throw new TypeError('Native dynamic service requires required string pathParams with unchanged schema');
  }
  let actual;
  try { actual = match(binding, samplePath); } catch { throw new TypeError('Invalid dynamic sample URL'); }
  if (!actual || names.some(name => actual[name] !== examples[name]))
    throw new TypeError('Dynamic sample URL must match the declared pathParams exactly');
  return binding;
}

/** One ordering shared by application dispatch and the native payment router. */
export function orderServiceRoutes(routes) {
  for (let i = 0; i < routes.length; i++) for (let j = i + 1; j < routes.length; j++) {
    const a = routes[i], b = routes[j];
    if (a.path === b.path) continue; // Distinct methods for the same path are valid.
    if (!a.binding.dynamic && !b.binding.dynamic && a.method === b.method &&
        a.path.replace(/(.+?)\/+$/, '$1').toLowerCase() === b.path.replace(/(.+?)\/+$/, '$1').toLowerCase())
      throw new TypeError('Case- or slash-ambiguous native service paths: ' + a.path + ' and ' + b.path);
    if (!a.binding.dynamic || !b.binding.dynamic) continue; // Concrete paths win.
    const left = a.binding.segments, right = b.binding.segments;
    if (left.length === right.length && left.every((s, k) => s.toLowerCase() === right[k].toLowerCase() ||
        s.startsWith(':') || right[k].startsWith(':'))) {
      throw new TypeError('Ambiguous dynamic service paths: ' + a.path + ' and ' + b.path);
    }
  }
  // Native router normalizes trailing slashes. Reject a static route that would
  // overlap a dynamic route only after this normalization.
  for (const a of routes.filter(r => !r.binding.dynamic && r.path.length > 1 && r.path.endsWith('/'))) {
    for (const b of routes.filter(r => r.binding.dynamic)) {
      if (b.binding.nativePattern.test(a.path.slice(0, -1))) throw new TypeError('Trailing-slash route overlaps a dynamic native path');
    }
  }
  return [...routes].sort((a, b) => Number(a.binding.dynamic) - Number(b.binding.dynamic));
}

/** Path precedence is independent of method: a concrete path returns its own 405. */
export function selectServiceRoute(routes, rawPath, method) {
  let selectedPath, params;
  for (const route of routes) {
    if (!route.binding.dynamic && asciiFold(route.path) !== asciiFold(rawPath)) continue;
    const found = route.binding.dynamic ? match(route.binding, rawPath) : Object.create(null);
    if (found === null) continue;
    selectedPath = route.path; params = found; break;
  }
  if (selectedPath === undefined) return null;
  // Keep fixed routes for distinct methods together when their native patterns
  // select the same case-insensitive path; otherwise a valid POST becomes 405.
  const matching = routes.filter(r => r.binding.dynamic
    ? r.path === selectedPath : asciiFold(r.path) === asciiFold(selectedPath));
  const route = matching.find(r => r.method === method);
  // Native static matching is case-insensitive, but a case-varied concrete
  // endpoint must not replace the price of a dynamic value with that spelling.
  // Preserve the original NATIVE_ROUTE_CASE_COLLISION rule before payment.
  if (route && !route.binding.dynamic && route.path !== rawPath &&
      routes.some(other => other.binding.dynamic && other.method === method &&
        match(other.binding, rawPath) !== null)) {
    throw Object.assign(new TypeError('NATIVE_ROUTE_CASE_COLLISION'), { status: 400 });
  }
  if (route?.binding.dynamic) {
    const decoded = decodeURIComponent(rawPath);
    const nativeRoute = routes.find(r => r.method === method && r.binding.nativePattern.test(decoded));
    if (nativeRoute !== route) throw Object.assign(new TypeError('NATIVE_ROUTE_CASE_COLLISION'), { status: 400 });
  }
  return { route, allow: matching.map(r => r.method), pathParams: params };
}

#!/usr/bin/env python3
"""Native operator CLI for the retained SDMX Macrobond catalog."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import signal
import stat
import sys
import tempfile
import threading

sys.dont_write_bytecode = True
HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
from connection import definition_xml, normalize_host

MAX_INPUT_BYTES = 8 * 1024 * 1024


def _integer(value):
    try:
        number = int(value)
    except (TypeError, ValueError) as error:
        raise argparse.ArgumentTypeError("Use a nonnegative integer.") from error
    if str(number) != str(value) or number < 0:
        raise argparse.ArgumentTypeError("Use a nonnegative integer.")
    return number


def _positive(value):
    number = _integer(value)
    if number < 1:
        raise argparse.ArgumentTypeError("Use an integer greater than zero.")
    return number


def _unique(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("The JSON input repeats the field " + repr(key) + ".")
        result[key] = value
    return result


def _nonfinite(value):
    raise ValueError("The JSON input contains a non-finite number.")


def _object(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise ValueError("The JSON input exceeds 8 MiB.")
    value = json.loads(raw, object_pairs_hook=_unique, parse_constant=_nonfinite)
    if not isinstance(value, dict):
        raise ValueError("Supply a JSON object.")
    return value


def _selection(filename):
    with Path(filename).expanduser().open("rb") as stream:
        return _object(stream.read(MAX_INPUT_BYTES + 1))


def _path(value):
    return Path(value).expanduser().resolve()


def _retained_output(path, raw):
    """Publish a whole selected file once, or recover its identical retained bytes."""
    path = _path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".macrobond-", delete=False) as stream:
            temporary = Path(stream.name)
            os.chmod(temporary, 0o600)
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary, path)
            recovered = False
        except FileExistsError:
            info = path.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_size != len(raw):
                raise ValueError("The selected output already contains a different file.")
            with path.open("rb") as stream:
                if stream.read(len(raw) + 1) != raw:
                    raise ValueError("The selected output already contains different content.")
            recovered = True
        if os.name == "posix":
            descriptor = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
        return {"path": str(path), "bytes": len(raw),
                "sha256": hashlib.sha256(raw).hexdigest(), "recovered": recovered}
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _ready_output(path, value, encode):
    """Replace only an earlier private ready record for this same catalog."""
    path = _path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        info = path.lstat()
        if not stat.S_ISREG(info.st_mode) or (os.name == "posix" and
                (info.st_mode & 0o077 or info.st_uid != os.geteuid())):
            raise ValueError("The selected ready file must be private.")
        old = _selection(path)
        if old.get("schema") != value["schema"] or old.get("catalog") != value["catalog"]:
            raise ValueError("The selected ready file belongs to another operation.")
    raw = encode(value) + b"\n"
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".macrobond-ready-", delete=False) as stream:
            temporary = Path(stream.name)
            os.chmod(temporary, 0o600)
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        temporary = None
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)
    return str(path)


def configure_runtime_temporary_directory(directory):
    """Keep native stderr and child SQLite spill in the selected private runtime."""
    def usable(value):
        if not value:
            return None
        candidate = Path(value).expanduser()
        if not candidate.is_absolute():
            return None
        try:
            info = candidate.lstat()
        except OSError:
            return None
        if not stat.S_ISDIR(info.st_mode) or not os.access(candidate, os.W_OK | os.X_OK):
            return None
        if os.name == "posix" and (info.st_uid != os.geteuid() or info.st_mode & 0o077):
            return None
        return candidate.resolve()

    selected = next((value for name in ("TMPDIR", "TEMP", "TMP")
                     if (value := usable(os.environ.get(name))) is not None), None)
    if selected is None:
        fallback = Path(directory).resolve() / "tmp"
        fallback.mkdir(mode=0o700, exist_ok=True)
        selected = usable(str(fallback))
        if selected is None:
            raise ValueError("The workspace tmp directory must be private and writable")
    tempfile.tempdir = str(selected)
    os.environ["TMPDIR"] = str(selected)
    sqlite = usable(os.environ.get("SQLITE_TMPDIR")) or selected
    os.environ["SQLITE_TMPDIR"] = str(sqlite)


def parser():
    result = argparse.ArgumentParser(
        description="Build and publish a Macrobond catalog from original retained SDMX projects.")
    result.add_argument("--catalog", help="private retained catalog directory")
    commands = result.add_subparsers(dest="command", required=True)
    commands.add_parser("init", help="create the catalog and its original SDMX workspace")
    commands.add_parser("state", help="read source projects, saved editions and current publication")

    for name, description in (
        ("import-sdmx", "import an original portable SDMX project"),
        ("import", "restore an exported Macrobond catalog and retained source projects"),
    ):
        command = commands.add_parser(name, help=description)
        command.add_argument("--file", required=True, help="exact retained ZIP packet")
    for name, description in (
        ("preview", "review selected original project revisions and series"),
        ("save", "save the reviewed edition using its stable operation_id"),
    ):
        command = commands.add_parser(name, help=description)
        command.add_argument("--file", required=True, help="edition-selection JSON")

    edition = commands.add_parser("edition", help="inspect a saved immutable edition")
    edition.add_argument("--id", required=True)
    series = commands.add_parser("series", help="page the selected edition's series")
    series.add_argument("--edition", required=True)
    series.add_argument("--offset", type=_integer, default=0)
    series.add_argument("--limit", type=_positive, default=50)
    series.add_argument("--query", default="")
    observations = commands.add_parser("observations", help="page one saved series' exact observations")
    observations.add_argument("--edition", required=True)
    observations.add_argument("--series", required=True)
    observations.add_argument("--offset", type=_integer, default=0)
    observations.add_argument("--limit", type=_positive, default=50)
    activate = commands.add_parser("activate", help="select the current edition with the original publication CAS")
    activate.add_argument("--edition", required=True)
    activate.add_argument("--expect-revision", required=True, type=_integer)
    activate.add_argument("--expect-current", required=True,
                          help="exact current edition ID from state, or none for an empty catalog")
    compare = commands.add_parser("compare", help="compare two retained editions")
    compare.add_argument("--before", required=True)
    compare.add_argument("--after", required=True)
    export = commands.add_parser("export", help="retain an edition and its source closure for another operator")
    export.add_argument("--edition", required=True)
    export.add_argument("--out", required=True)
    provider = commands.add_parser("provider", help="read the catalog through the original Macrobond wire serializer")
    provider.add_argument("--command", dest="provider_command", required=True)
